import{_ as a,o as e,c as d,ai as r}from"./chunks/framework.ampVZV4B.js";const _=JSON.parse('{"title":"Python · 03 框架与生态","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/backend/python/03-frameworks.md","filePath":"tech-system/backend/python/03-frameworks.md"}'),o={name:"tech-system/backend/python/03-frameworks.md"};function l(n,t,i,s,h,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="python-·-03-框架与生态" tabindex="-1">Python · 03 框架与生态 <a class="header-anchor" href="#python-·-03-框架与生态" aria-label="Permalink to “Python · 03 框架与生态”">​</a></h1><blockquote><p>语言快，不代表框架随便选。只谈 <strong>我会用哪个、为什么。</strong></p></blockquote><h2 id="_1-fastapi-默认首选" tabindex="-1">1. FastAPI（默认首选） <a class="header-anchor" href="#_1-fastapi-默认首选" aria-label="Permalink to “1. FastAPI（默认首选）”">​</a></h2><ul><li>写 AI / 工具类 HTTP 服务最常用</li><li>类型注解 → 自动校验与 OpenAPI 文档，和「对外契约」很搭</li><li>原生 async，适合等模型、等下游</li></ul><p><strong>适合：</strong> 内部 API、模型代理、给 Java 调用的胶水层、异步任务触发器。</p><p><strong>注意：</strong></p><ul><li>别在 async 路由里跑阻塞代码</li><li>重任务：接口只投递任务，真正生成走队列/后台 worker</li><li>鉴权：内部服务可用 API Key / mTLS；对公网要认真做</li></ul><hr><h2 id="_2-flask" tabindex="-1">2. Flask <a class="header-anchor" href="#_2-flask" aria-label="Permalink to “2. Flask”">​</a></h2><ul><li>轻、灵活、历史包袱项目多</li><li>适合非常小的脚本服务或遗留维护</li></ul><p><strong>判断：</strong> 新项目我更愿意直接 FastAPI；维护老 Flask 再学够用即可。</p><hr><h2 id="_3-django" tabindex="-1">3. Django <a class="header-anchor" href="#_3-django" aria-label="Permalink to “3. Django”">​</a></h2><ul><li>「电池全」：Admin、ORM、用户体系齐全</li><li>适合要快速出带后台的完整站点</li></ul><p><strong>判断：</strong> 我的主业务已在 Java；Django 不是默认选项。只有「独立小站 + 强 Admin」才考虑。</p><hr><h2 id="_4-周边生态-按需" tabindex="-1">4. 周边生态（按需） <a class="header-anchor" href="#_4-周边生态-按需" aria-label="Permalink to “4. 周边生态（按需）”">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>常见选择</th><th>用法</th></tr></thead><tbody><tr><td>HTTP 客户端</td><td><code>httpx</code>（同步/异步）、<code>requests</code></td><td>调模型与内部 API</td></tr><tr><td>校验 / 设置</td><td>Pydantic v2、<code>pydantic-settings</code></td><td>配置与 DTO</td></tr><tr><td>任务队列</td><td>Celery / RQ / 自研表状态</td><td>有多 worker 需求再上 Celery</td></tr><tr><td>AI 编排</td><td>官方 SDK 优先；LangChain 等按需</td><td>先跑通官方，再引入重框架</td></tr><tr><td>数据</td><td>pandas（分析时）</td><td>不要在线 API 路径里无界吃内存</td></tr><tr><td>包管理</td><td><code>uv</code> / <code>poetry</code> / <code>pip+venv</code></td><td>锁版本，可复现</td></tr></tbody></table><h3 id="ai-相关特别提醒" tabindex="-1">AI 相关特别提醒 <a class="header-anchor" href="#ai-相关特别提醒" aria-label="Permalink to “AI 相关特别提醒”">​</a></h3><ul><li>框架会过时；<strong>超时、重试、限流、成本与日志</strong> 不会过时——自己管住</li><li>Prompt 与模型参数要可配置、可版本，别写死在代码魔法字符串满天飞</li><li>多模型适配：统一「请求/响应/错误」层，类似 Java 侧任务编排思想</li></ul><hr><h2 id="_5-选择表" tabindex="-1">5. 选择表 <a class="header-anchor" href="#_5-选择表" aria-label="Permalink to “5. 选择表”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>选择</th></tr></thead><tbody><tr><td>AI / 自动化 API</td><td><strong>FastAPI</strong></td></tr><tr><td>几行脚本 + 临时 HTTP</td><td>Flask 或甚至不写框架</td></tr><tr><td>带后台的独立小站</td><td>Django（少用）</td></tr><tr><td>只跑批处理</td><td>脚本 + cron / 系统定时；不必硬上 Web</td></tr></tbody></table><p>下一篇：<a href="./04-engineering.html">04 工程实践</a></p>',24)])])}const b=a(o,[["render",l]]);export{_ as __pageData,b as default};
